-- =====================================================================
-- V7_9 — Plantowner dashboard page (live KPI tiles).
-- =====================================================================

INSERT INTO page_definition (tenant_id, code, title, description, category, status) SELECT 1,'pico:plantowner-dashboard','Plantowner Dashboard','Live KPIs across dispatch, masters, workflow.','Dashboard','PUBLISHED' WHERE NOT EXISTS (SELECT 1 FROM page_definition WHERE tenant_id=1 AND code='pico:plantowner-dashboard');

INSERT INTO page_version (page_id, version, status, body_json, rationale, published_at) SELECT p.id, 1, 'PUBLISHED', '{"schemaVersion":2,"layout":{"type":"Grid","props":{"gap":16,"style":{"gridTemplateColumns":"repeat(auto-fit, minmax(180px, 1fr))","padding":16}},"children":[{"type":"KPI","props":{"label":"Gate Passes (Total)","intervalMs":30000,"dataSource":{"type":"entity","entity":"GatePass","filter":{"and":[{"field":"tenant_id","op":"eq","value":"ctx:tenantId"}]}}}},{"type":"KPI","props":{"label":"Closed","intervalMs":30000,"dataSource":{"type":"entity","entity":"GatePass","filter":{"and":[{"field":"tenant_id","op":"eq","value":"ctx:tenantId"},{"field":"status","op":"eq","value":"CLOSED"}]}}}},{"type":"KPI","props":{"label":"In Progress","intervalMs":30000,"dataSource":{"type":"entity","entity":"GatePass","filter":{"and":[{"field":"tenant_id","op":"eq","value":"ctx:tenantId"},{"field":"status","op":"nin","value":["CLOSED","QC_REJECTED","DRAFT"]}]}}}},{"type":"KPI","props":{"label":"Workflow Events","intervalMs":30000,"dataSource":{"type":"entity","entity":"WorkflowEvent","filter":{"and":[{"field":"tenant_id","op":"eq","value":"ctx:tenantId"}]}}}},{"type":"KPI","props":{"label":"Active Drivers","dataSource":{"type":"entity","entity":"Driver","filter":{"and":[{"field":"tenant_id","op":"eq","value":"ctx:tenantId"},{"field":"active","op":"eq","value":1}]}}}},{"type":"KPI","props":{"label":"Vehicles in Fleet","dataSource":{"type":"entity","entity":"Vehicle","filter":{"and":[{"field":"tenant_id","op":"eq","value":"ctx:tenantId"}]}}}},{"type":"KPI","props":{"label":"Active Tanks","dataSource":{"type":"entity","entity":"TankLocation","filter":{"and":[{"field":"tenant_id","op":"eq","value":"ctx:tenantId"},{"field":"active","op":"eq","value":1}]}}}},{"type":"KPI","props":{"label":"Vendors","dataSource":{"type":"entity","entity":"Vendor","filter":{"and":[{"field":"tenant_id","op":"eq","value":"ctx:tenantId"}]}}}}]}}', 'V7_9', CURRENT_TIMESTAMP FROM page_definition p WHERE p.tenant_id=1 AND p.code='pico:plantowner-dashboard' AND NOT EXISTS (SELECT 1 FROM page_version v WHERE v.page_id = p.id AND v.version = 1);

UPDATE page_definition SET current_version_id = (SELECT id FROM page_version WHERE page_id = page_definition.id AND version = 1 LIMIT 1) WHERE tenant_id=1 AND code='pico:plantowner-dashboard' AND current_version_id IS NULL;
